// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        // Fund the contract with a fuzzed amount, then let its owner (this test
        // contract, the deployer) invoke sudicideAnyone(). The reference
        // self-destructs and sends the whole balance to the owner, so no funds
        // remain on c; the mutant keeps them.
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.sudicideAnyone();
        assertTrue(address(c).balance == 0, "funds must be drained on owner suicide");
    }
}
